    void saveToFile(const std::string& filename) const {
        std::ofstream file(filename);
        for (const auto& [name, stats] : ratings) {
            file << name << ',' << stats.first << ',' << stats.second << '\n';
        }
    }

    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        std::string line;
        while (std::getline(file, line)) {
            size_t pos1 = line.find(',');
            size_t pos2 = line.find(',', pos1 + 1);
            std::string name = line.substr(0, pos1);
            int wins = std::stoi(line.substr(pos1 + 1, pos2 - pos1 - 1));
            int losses = std::stoi(line.substr(pos2 + 1));
            ratings[name] = {wins, losses};
        }
    }

    void displayRatings(sf::RenderWindow& window) const {
        sf::Font font;
        font.loadFromFile("arial.ttf");

        sf::Text text;
        text.setFont(font);
        text.setCharacterSize(24);
        text.setFillColor(sf::Color::White);

        int yPosition = 50;
        for (const auto& [name, stats] : ratings) {
            std::string textContent = name + ": Wins: " + std::to_string(stats.first) + ", Losses: " + std::to_string(stats.second);
            text.setString(textContent);
            text.setPosition(50, yPosition);
            window.draw(text);
            yPosition += 30;
        }
    }
};

// View: Handles UI and Graphics
class ChessView {
public:
    ChessView(sf::RenderWindow& window) : window_(window) {}

    void drawBoard() {
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                sf::RectangleShape square(sf::Vector2f(50, 50));
                square.setPosition(i * 50, j * 50);
                square.setFillColor((i + j) % 2 == 0 ? sf::Color::White : sf::Color::Black);
                window_.draw(square);
            }
        }
    }

    void drawSettingsPanel() {
        sf::RectangleShape panel(sf::Vector2f(200, 100));
        panel.setPosition(0, 400);
        panel.setFillColor(sf::Color::Green);
        window_.draw(panel);
    }

    void drawRatings(const PlayerRating& ratingSystem) {
        ratingSystem.displayRatings(window_);
    }

private:
    sf::RenderWindow& window_;
};

// Controller: Handles user inputs
class ChessController {
public:
    ChessController(ChessModel& model, ChessView& view, PlayerRating& ratingSystem)
        : model_(model), view_(view), ratingSystem_(ratingSystem) {}

    void startGame() {
        model_.startGame();
        view_.drawBoard(); // Redraw the board after starting the game
    }

    void updateRatings(const std::string& playerName, bool isWin) {
        if (isWin) {
            ratingSystem_.addWin(playerName);
        } else {
            ratingSystem_.addLoss(playerName);
        }
        ratingSystem_.saveToFile("ratings.txt");
    }

    void showRatings() {
        view_.drawRatings(ratingSystem_);
    }

private:
    ChessModel& model_;
    ChessView& view_;
    PlayerRating& ratingSystem_;
};

int main() {
    sf::RenderWindow window(sf::VideoMode(800, 600), "Chess Game");

    ChessModel game;
    PlayerRating ratingSystem;
    ChessView view(window);
    ChessController controller(game, view, ratingSystem);

    ratingSystem.loadFromFile("ratings.txt");

    sf::Sprite startButtonSprite; // Assume sprite is initialized elsewhere
    sf::Sprite ratingButtonSprite; // Assume sprite is initialized elsewhere

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();

            if (event.type == sf::Event::MouseButtonPressed) {
                if (event.mouseButton.button == sf::Mouse::Left) {
                    if (startButtonSprite.getGlobalBounds().contains(event.mouseButton.x, event.mouseButton.y)) {
                        controller.startGame();
                    } else if (ratingButtonSprite.getGlobalBounds().contains(event.mouseButton.x, event.mouseButton.y)) {
                        controller.showRatings();
                    }
                }
            }
        }

        window.clear();

        view.drawBoard();
        view.drawSettingsPanel();
        controller.showRatings(); // Always display ratings for demonstration purposes

        window.display();
    }

    ratingSystem.saveToFile("ratings.txt");

    return 0;
}
