// Function to decrypt descriptor using OpenSSL
std::string DecryptDescriptor(const std::string& encryptedDescriptor, const std::string& privateKey) {
    BIO *bio = BIO_new_mem_buf(privateKey.c_str(), -1);
    EVP_PKEY *pkey = PEM_read_bio_PrivateKey(bio, NULL, NULL, NULL);
    BIO_free(bio);

    BIO *cipherBio = BIO_new_mem_buf(encryptedDescriptor.c_str(), -1);
    BIO *decryptBio = BIO_new(BIO_f_base64());
    BIO_push(decryptBio, cipherBio);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL))
        throw std::runtime_error("Failed to initialize decryption context.");

    unsigned char *plaintext = nullptr;
    int plaintextLen;
    if (!EVP_PKEY_decrypt(ctx, plaintext, &plaintextLen, reinterpret_cast<const unsigned char*>(encryptedDescriptor.data()), encryptedDescriptor.size()))
        throw std::runtime_error("Failed to decrypt descriptor.");

    BIO_free_all(decryptBio);
    EVP_CIPHER_CTX_free(ctx);
    EVP_PKEY_free(pkey);

    return std::string(reinterpret_cast<char*>(plaintext), plaintextLen);
}

